mapper.select:
/* Location01Mapper.selectConsentStatusList */ SELECT X.userCd , X.userId , X.userNm , X.userTypeCd , X.nodeCd , X.nodeNm , X.consentState , X.lastActionDtime , X.purgeCount FROM ( SELECT U.USER_CD AS userCd , U.USER_ID AS userId , U.USER_NM AS userNm , 'REGULAR' AS userTypeCd , U.NODE_CD AS nodeCd , N.NODE_NM AS nodeNm , AS consentState , DATE_FORMAT(H.LAST_DTIME, '%Y-%m-%d %H:%i') AS lastActionDtime , IFNULL(P.CNT, 0) AS purgeCount FROM TB_USER U LEFT OUTER JOIN TB_SITE_NODE N ON (N.CMPNY_CD = U.CMPNY_CD AND N.SITE_CD = U.SITE_CD AND N.NODE_CD = U.NODE_CD) LEFT OUTER JOIN TB_TERMS_USER_AGR_MGMT M ON (M.CMPNY_CD = U.CMPNY_CD AND M.USER_CD = U.USER_CD AND M.TERMS_ID = '005' AND M.TERMS_VERSION = #{termsVersion}) LEFT OUTER JOIN ( SELECT CMPNY_CD, USER_CD, MAX(ACTION_DTIME) AS LAST_DTIME FROM TB_TERMS_USER_AGR_HIST WHERE CMPNY_CD = #{cmpnyCd} AND TERMS_ID = '005' GROUP BY CMPNY_CD, USER_CD ) H ON (H.CMPNY_CD = U.CMPNY_CD AND H.USER_CD = U.USER_CD) LEFT OUTER JOIN ( SELECT CMPNY_CD, USER_CD, COUNT(*) AS CNT FROM TB_LOCATION_PURGE_HIST WHERE CMPNY_CD = #{cmpnyCd} GROUP BY CMPNY_CD, USER_CD ) P ON (P.CMPNY_CD = U.CMPNY_CD AND P.USER_CD = U.USER_CD) WHERE U.CMPNY_CD = #{cmpnyCd} AND U.SITE_CD = #{siteCd} AND U.USE_YN = 'Y'
AND U.NODE_CD = #{scopeNodeCd}
UNION ALL
/* 일용직 계통 — 부서 개념이 없어 nodeCd/nodeNm 은 NULL 이다. scopeNodeCd 가 지정된 경우(부서 관리자)에는 대상에서 제외한다(부서 스코프 밖). */ SELECT D.USER_CD , D.USER_ID , D.USER_NM , 'DAILY' , NULL , NULL , , DATE_FORMAT(H.LAST_DTIME, '%Y-%m-%d %H:%i') , IFNULL(P.CNT, 0) FROM TB_DAILY_USER D LEFT OUTER JOIN TB_TERMS_USER_AGR_MGMT M ON (M.CMPNY_CD = D.CMPNY_CD AND M.USER_CD = D.USER_CD AND M.TERMS_ID = '005' AND M.TERMS_VERSION = #{termsVersion}) LEFT OUTER JOIN ( SELECT CMPNY_CD, USER_CD, MAX(ACTION_DTIME) AS LAST_DTIME FROM TB_TERMS_USER_AGR_HIST WHERE CMPNY_CD = #{cmpnyCd} AND TERMS_ID = '005' GROUP BY CMPNY_CD, USER_CD ) H ON (H.CMPNY_CD = D.CMPNY_CD AND H.USER_CD = D.USER_CD) LEFT OUTER JOIN ( SELECT CMPNY_CD, USER_CD, COUNT(*) AS CNT FROM TB_LOCATION_PURGE_HIST WHERE CMPNY_CD = #{cmpnyCd} GROUP BY CMPNY_CD, USER_CD ) P ON (P.CMPNY_CD = D.CMPNY_CD AND P.USER_CD = D.USER_CD) WHERE D.CMPNY_CD = #{cmpnyCd} AND D.SITE_CD = #{siteCd} AND D.USE_YN = 'Y'
AND 1 = 0
) X
/* 확인이 필요한 사람만 — 동의 상태가 아닌 전원(중지·재동의대기·철회). */ WHERE X.consentState <> 'AGREED'
ORDER BY CASE X.consentState WHEN 'WITHDRAWN' THEN 1 WHEN 'SUSPENDED' THEN 2 WHEN 'PENDING_REAGREE' THEN 3 ELSE 4 END , X.userNm

/* Location01Mapper.countUserInScope */
SELECT COUNT(1)
FROM (
    SELECT U.USER_CD
    FROM TB_USER U
    WHERE U.CMPNY_CD = #{cmpnyCd}
      AND U.SITE_CD  = #{siteCd}
      AND U.USER_CD  = #{userCd}

      AND U.NODE_CD = #{scopeNodeCd}


    UNION ALL

    SELECT D.USER_CD
    FROM TB_DAILY_USER D
    WHERE D.CMPNY_CD = #{cmpnyCd}
      AND D.SITE_CD  = #{siteCd}
      AND D.USER_CD  = #{userCd}

      AND 1 = 0

) X
